## Calculator Deluxe

### Full State

```xiom
type Calculator {
  display: Float64;
  memory: Float64;
  history: Vec[Str];
  history_index: Int;
}

fn new_calculator() -> Calculator {
  Calculator{ display: 0.0, memory: 0.0, history: Vec[Str].new(), history_index: 0 }
}
```

### Operation Enum

```xiom
enum Op {
  Add; Subtract; Multiply; Divide;
  Power; SquareRoot;
  MemoryStore; MemoryRecall; MemoryClear; MemoryAdd;
  Clear; ClearAll;
}
```

### Execute Operation

```xiom
fn execute(calc: &mut Calculator, op: Op, operand: Float64) -> Float64 {
  match op {
    Op.Add => { calc.display = calc.display + operand; },
    Op.Subtract => { calc.display = calc.display - operand; },
    Op.Multiply => { calc.display = calc.display * operand; },
    Op.Divide => {
      if operand == 0.0 { return calc.display; };
      calc.display = calc.display / operand;
    },
    Op.MemoryStore => { calc.memory = calc.display; },
    Op.MemoryRecall => { calc.display = calc.memory; },
    Op.MemoryClear => { calc.memory = 0.0; },
    Op.MemoryAdd => { calc.memory = calc.memory + calc.display; },
    Op.Clear => { calc.display = 0.0; },
    Op.ClearAll => { calc.display = 0.0; calc.memory = 0.0; },
    Op.Power => {
      let mut result = 1.0;
      let mut i = 0;
      while (i as Float64) < operand { result = result * calc.display; i += 1; };
      calc.display = result;
    },
    Op.SquareRoot => { }
  };

  add_to_history(calc, op, operand);
  calc.display
}
```

### History Management

```xiom
fn add_to_history(calc: &mut Calculator, op: Op, operand: Float64) {
  let entry = format("{} {} = {}", op_name(op), operand, calc.display);
  calc.history.push(entry);

  if calc.history.len() > 5 {
    calc.history.remove(0);
  };
}

fn print_history(calc: &Calculator) {
  io.println("--- History ---");
  let mut i = 0;
  while i < calc.history.len() {
    io.println(calc.history.get(i).unwrap());
    i += 1;
  };
}
```

