use xiom.io;
type CalcDeluxe = {
  value: Int;
  memory: Int;
  ops_done: Int;
}

fn add_op(calc: &mut CalcDeluxe, n: Int) {
  calc.value = calc.value + n;
  calc.ops_done += 1;
}

fn mem_store(calc: &mut CalcDeluxe) {
  calc.memory = calc.value;
}

fn mem_recall(calc: &mut CalcDeluxe) {
  calc.value = calc.memory;
}

fn clear(calc: &mut CalcDeluxe) {
  calc.value = 0;
}

fn main() -> Int {
  var calc = CalcDeluxe{ value: 0, memory: 0, ops_done: 0 };
  add_op(&mut calc, 10);
  add_op(&mut calc, 5);
  mem_store(&mut calc);
  clear(&mut calc);
  mem_recall(&mut calc);
  io.println(calc.value.to_str());
  return 0;
}
